import { decodeForm, isRecord, type Country } from '@quote/contract';

export const FORM_UID = 'api::quote-content.form-configuration';

function projectField(raw: unknown): unknown {
  if (!isRecord(raw)) return null;
  const { fieldKey, label, helpText, errorMessage, kind, required, order, purpose, defaultValue, rules, options } = raw;
  return {
    id: fieldKey,
    label,
    helpText: helpText === null ? '' : helpText,
    errorMessage,
    kind,
    required,
    order,
    purpose: purpose ?? undefined,
    defaultValue: defaultValue ?? undefined,
    rules: Array.isArray(rules) ? rules.map((rule: unknown) => isRecord(rule)
      ? { operator: rule['operator'], argument: rule['argument'] ?? undefined, message: rule['message'] }
      : null) : rules,
    options: Array.isArray(options) && (kind === 'select' || options.length)
      ? options.map((option: unknown) => isRecord(option)
        ? { id: option['optionKey'], label: option['label'] } : null)
      : undefined,
  };
}

export function projectForm(document: unknown, country: Country) {
  if (!isRecord(document) || !Array.isArray(document['fields'])) return null;
  return decodeForm({
    schemaVersion: 1,
    country: document['country'],
    fields: document['fields'].map(projectField),
  }, country);
}
EOF
cat > backend/src/api/quote-content/controllers/quote-content.ts <<'EOF'
import { isCountry } from '@quote/contract';
import { FORM_UID, projectForm } from '../form-projection';

type ReadContext = {
  params: Record<string, unknown>;
  querystring: string;
  set(name: string, value: string): void;
  status: number;
  body: unknown;
};

export default {
  async readForm(ctx: ReadContext) {
    ctx.set('Cache-Control', 'no-store');
    const fail = (status: number, code: string) => {
      ctx.body = { error: { code } };
      ctx.status = status;
    };

    const country = ctx.params['country'];
    if (!isCountry(country)) return fail(404, 'UNSUPPORTED_COUNTRY');
    if (ctx.querystring) return fail(400, 'INVALID_REQUEST');

    let documents;
    try {
      documents = await strapi.documents(FORM_UID).findMany({
        status: 'published',
        filters: { country },
        populate: { fields: { populate: ['options', 'rules'] } },
        limit: 2,
      });
    } catch {
      strapi.log.error('Quote form document retrieval failed.');
      return fail(503, 'CONTENT_UNAVAILABLE');
    }

    if (!documents.length) return fail(404, 'FORM_NOT_PUBLISHED');
    const form = documents.length === 1 ? projectForm(documents[0], country) : null;
    if (!form) {
      strapi.log.warn('A published quote form configuration was rejected.');
      return fail(503, 'FORM_UNAVAILABLE');
    }
    ctx.body = form;
    ctx.status = 200;
  },
};
EOF
