cat > backend/src/index.ts <<'EOF'
import type { Core } from '@strapi/strapi';
import { FORM_UID } from './api/quote-content/form-projection';
import { READ_FORM_ACTION } from './api/quote-content/routes/quote-content';
import { seedForm } from './seed-forms';

export default {
  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
    const seedState = strapi.store({ type: 'core', name: 'quote-content' });
    if (await seedState.get({ key: 'us01-seeded' })) return;

    const roles = strapi.db.query('plugin::users-permissions.role');
    const publicRole = await roles.findOne({ where: { type: 'public' } });
    if (!publicRole) throw new Error('The Public role is unavailable during quote initialization.');
    const permissions = strapi.db.query('plugin::users-permissions.permission');
    const existing = await permissions.findOne({
      where: { action: READ_FORM_ACTION, role: publicRole.id },
    });
    if (!existing) await permissions.create({ data: { action: READ_FORM_ACTION, role: publicRole.id } });

    for (const country of ['co', 'cl'] as const) {
      const documents = strapi.documents(FORM_UID);
      const draft = await documents.findFirst({ status: 'draft', filters: { country } });
      if (!draft) await documents.create({ data: seedForm(country), status: 'published' });
    }
    await seedState.set({ key: 'us01-seeded', value: true });
  },
};
EOF
cat > backend/scripts/start.mjs <<'EOF'
import { randomBytes } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { spawn } from 'node:child_process';
import { createRequire } from 'node:module';

const require = createRequire(import.meta.url);
const database = resolve(process.env.DATABASE_FILENAME ?? '.data/strapi.sqlite');
const dataDirectory = dirname(database);
const secretFile = join(dataDirectory, 'strapi-local-secrets.json');
mkdirSync(dataDirectory, { recursive: true });
const secret = () => randomBytes(32).toString('base64url');
try {
  writeFileSync(secretFile, JSON.stringify({
    APP_KEYS: [secret(), secret(), secret(), secret()].join(','),
    ADMIN_JWT_SECRET: secret(),
    API_TOKEN_SALT: secret(),
    TRANSFER_TOKEN_SALT: secret(),
    JWT_SECRET: secret(),
    ENCRYPTION_KEY: secret(),
  }), { mode: 0o600, flag: 'wx' });
} catch (error) {
  if (error.code !== 'EEXIST') throw error;
}
const environment = JSON.parse(readFileSync(secretFile, 'utf8'));
const directory = dirname(require.resolve('@strapi/strapi/package.json'));
const command = process.argv[2] === 'develop' ? 'develop' : 'start';
const server = spawn(process.execPath, [join(directory, 'bin/strapi.js'), command], {
  env: { ...environment, ...process.env, DATABASE_FILENAME: database },
  stdio: 'inherit',
});
for (const signal of ['SIGINT', 'SIGTERM']) process.on(signal, () => server.kill(signal));
server.on('exit', (code) => { process.exitCode = code ?? 1; });
EOF
