        if (!rulePasses(rule, value, now)) failures.push(rule.message);
      }
    } else if (!failures.length) failures.push(field.errorMessage);
  }
  return failures;
}

export function reconcileDraft(
  fields: readonly FieldDefinition[],
  draft: QuoteDraft,
): QuoteDraft {
  const entries: Array<[string, DraftEntry]> = [];
  for (const field of fields) {
    if (!Object.hasOwn(draft, field.id)) {
      if (field.defaultValue !== undefined)
        entries.push([
          field.id,
          { kind: field.kind, value: field.defaultValue },
        ]);
      continue;
    }
    const { kind, value } = draft[field.id];
    const compatibleKind =
      kind === field.kind ||
      (kind === "text" && field.kind === "date") ||
      (kind === "date" && field.kind === "text");
    if (compatibleKind && (value === null || represents(field, value)))
      entries.push([field.id, { kind: field.kind, value }]);
  }
  return Object.fromEntries(entries);
}
import type { Core } from "@strapi/strapi";
import { FORM_UID } from "./api/quote-content/form-projection";
import { READ_FORM_ACTION } from "./api/quote-content/routes/quote-content";
import { seedForm } from "./seed-forms";

export default {
  async bootstrap({ strapi }: { strapi: Core.Strapi }) {
    const seedState = strapi.store({ type: "core", name: "quote-content" });
    if (await seedState.get({ key: "us01-seeded" })) return;

    const roles = strapi.db.query("plugin::users-permissions.role");
    const publicRole = await roles.findOne({ where: { type: "public" } });
    if (!publicRole)
      throw new Error(
        "The Public role is unavailable during quote initialization.",
      );
    const permissions = strapi.db.query("plugin::users-permissions.permission");
    const existing = await permissions.findOne({
      where: { action: READ_FORM_ACTION, role: publicRole.id },
    });
    if (!existing)
      await permissions.create({
        data: { action: READ_FORM_ACTION, role: publicRole.id },
      });

    for (const country of ["co", "cl"] as const) {
      const documents = strapi.documents(FORM_UID);
      const draft = await documents.findFirst({
        status: "draft",
        filters: { country },
      });
      if (!draft)
        await documents.create({
          data: seedForm(country),
          status: "published",
        });
    }
    await seedState.set({ key: "us01-seeded", value: true });
  },
};
import type { ConfigContext } from "./environment";

export default ({ env }: ConfigContext) => ({
  "users-permissions": { config: { jwtSecret: env("JWT_SECRET") } },
});
import { decodeForm, isRecord, type Country } from "@quote/contract";

export const FORM_UID = "api::quote-content.form-configuration";

// Keep scalars inside an object in Strapi JSON fields so SQLite preserves
// Boolean and string types through storage and editorial round trips.
function scalar(raw: unknown): unknown {
  if (raw === null || raw === undefined) return undefined;
  return isRecord(raw) && Object.keys(raw).length === 1 && raw["value"] != null
    ? raw["value"]
    : raw;
}

function projectField(raw: unknown): unknown {
  if (!isRecord(raw)) return null;
  const {
    fieldKey,
    label,
    helpText,
    errorMessage,
    kind,
    required,
    order,
    purpose,
    defaultValue,
    rules,
    options,
  } = raw;
  return {
    id: fieldKey,
    label,
    helpText: helpText === null ? "" : helpText,
    errorMessage,
    kind,
    required,
    order,
    purpose: purpose ?? undefined,
    defaultValue: scalar(defaultValue),
    rules: Array.isArray(rules)
      ? rules.map((rule: unknown) =>
          isRecord(rule)
            ? {
                operator: rule["operator"],
                argument: scalar(rule["argument"]),
                message: rule["message"],
              }
            : null,
        )
      : rules,
    options:
      Array.isArray(options) && (kind === "select" || options.length)
        ? options.map((option: unknown) =>
            isRecord(option)
              ? { id: option["optionKey"], label: option["label"] }
              : null,
          )
        : undefined,
  };
}

export function projectForm(document: unknown, country: Country) {
  if (!isRecord(document) || !Array.isArray(document["fields"])) return null;
  return decodeForm(
    {
      schemaVersion: 1,
      country: document["country"],
      fields: document["fields"].map(projectField),
    },
    country,
  );
}
